function teckoR(html) {
  if (!html || html.length < 50) return ""

  // Step 1: 提取段落
  var ps = extractP(html)
  if (ps.length === 0) return ""

  console.log("=== Tecko-R 评分表 ===")
  console.log("提取段落数: " + ps.length)

  // Step 2: 结构过滤（标记 isAd + 初始化 adTTL）
  structFilter(ps)

  // Step 3: 基础评分
  for (var i = 0; i < ps.length; i++) {
    ps[i].score = baseScore(ps[i])
    if (ps[i].isAd) {
      ps[i].score = Math.min(ps[i].score, 10)
    }
  }

  // Step 3.5: LQB 连续低质量检测
  lqb(ps)

  // Step 3.6: adTTL 广告衰减传播
  adTTL(ps)

  // 打印评分表
  console.log("┌────┬───────┬───────┬─────┬───────┬───────┬──────────────────────────────────┐")
  console.log("│ #  │ score │ isAd  │ LQB │ adTTL │ final │ text                             │")
  console.log("├────┼───────┼───────┼─────┼───────┼───────┼──────────────────────────────────┤")
  for (var p = 0; p < ps.length; p++) {
    var item = ps[p]
    var textPreview = item.text.replace(/<[^>]+>/g, "").substring(0, 30)
    textPreview = textPreview.replace(/\n/g, " ").replace(/\r/g, "")
    var finalScore = item.score
    console.log("│ " + pad(p, 2) + " │ " + pad(item.score, 5) + " │ " + pad(item.isAd ? "Y" : "N", 5) + " │ " + pad(item.lowScoreStreak, 3) + " │ " + pad(item.adTTL, 5) + " │ " + pad(finalScore, 5) + " │ " + padRight(textPreview, 32) + " │")
  }
  console.log("└────┴───────┴───────┴─────┴───────┴───────┴──────────────────────────────────┘")

  // Ring Buffer: 超出 MAX_P 时淘汰低分段
  if (ps.length > MAX_P) {
    console.log("RingBuffer: 淘汰 " + (ps.length - MAX_P) + " 个低分段")
    ps.sort(function (a, b) { return b.score - a.score })
    ps = ps.slice(0, MAX_P)
  }

  // Step 4: 单向邻域增强
  var sm = smooth(ps)

  // Step 5: Kadane-lite
  var region = kadane(sm)

  console.log("Kadane 选择区间: [" + region.bestL + ", " + region.bestR + "]")

  // 打印 Kadane 选择的段落
  console.log("选中段落:")
  for (var j = region.bestL; j <= region.bestR; j++) {
    var selText = ps[j].text.replace(/<[^>]+>/g, "").substring(0, 50)
    console.log("  [" + j + "] score=" + sm[j] + " text=" + selText)
  }

  // 拼接输出
  var out = ""
  for (var k = region.bestL; k <= region.bestR; k++) {
    out += ps[k].text
  }

  return out
}

function pad(n, width) {
  var s = String(n)
  while (s.length < width) s = " " + s
  return s
}

function padRight(s, width) {
  if (s.length >= width) return s.substring(0, width)
  while (s.length < width) s = s + " "
  return s
}
